create extension if not exists pgcrypto with schema extensions;
create table if not exists public.glitch_connector_config(id boolean primary key default true check(id),signing_secret text not null);
insert into public.glitch_connector_config(id,signing_secret) values(true,'REPLACE_WITH_CONNECTOR_SIGNING_SECRET') on conflict(id) do nothing;
revoke all on public.glitch_connector_config from public,anon,authenticated;
create table if not exists public.glitch_user_connectors(user_id uuid not null references auth.users(id) on delete cascade,provider text not null check(provider in('google','github','vercel')),account_email text not null default '',scopes text[] not null default '{}',ciphertext text not null,iv text not null,tag text not null,expires_at timestamptz,connected_at timestamptz not null default now(),primary key(user_id,provider));
alter table public.glitch_user_connectors enable row level security;revoke all on public.glitch_user_connectors from public,anon,authenticated;grant select on public.glitch_user_connectors to authenticated;
drop policy if exists "Glitch connector owner can read own connection" on public.glitch_user_connectors;
create policy "Glitch connector owner can read own connection" on public.glitch_user_connectors for select to authenticated using(auth.uid()=user_id);
create or replace function public.store_glitch_connector(p_user_id uuid,p_provider text,p_account_email text,p_scopes text[],p_ciphertext text,p_iv text,p_tag text,p_expires_at timestamptz,p_signature text) returns boolean language plpgsql security definer set search_path='' as $$
declare s text;p text;e text;
begin select signing_secret into s from public.glitch_connector_config where id=true;if s is null or s='REPLACE_WITH_CONNECTOR_SIGNING_SECRET' then raise exception 'Set connector signing secret first';end if;
p=concat_ws('|',p_user_id::text,p_provider,coalesce(p_account_email,''),array_to_string(p_scopes,','),p_ciphertext,p_iv,p_tag);e=encode(extensions.hmac(convert_to(p,'UTF8'),convert_to(s,'UTF8'),'sha256'),'hex');if e<>p_signature then raise exception 'Invalid connector signature';end if;
insert into public.glitch_user_connectors(user_id,provider,account_email,scopes,ciphertext,iv,tag,expires_at) values(p_user_id,p_provider,coalesce(p_account_email,''),coalesce(p_scopes,'{}'),p_ciphertext,p_iv,p_tag,p_expires_at) on conflict(user_id,provider) do update set account_email=excluded.account_email,scopes=excluded.scopes,ciphertext=excluded.ciphertext,iv=excluded.iv,tag=excluded.tag,expires_at=excluded.expires_at,connected_at=now();return true;end $$;
revoke all on function public.store_glitch_connector(uuid,text,text,text[],text,text,text,timestamptz,text) from public;grant execute on function public.store_glitch_connector(uuid,text,text,text[],text,text,text,timestamptz,text) to anon,authenticated;
create or replace function public.list_glitch_connectors() returns table(provider text,account_email text,scopes text[],connected_at timestamptz,expires_at timestamptz) language sql security definer set search_path='' as $$ select provider,account_email,scopes,connected_at,expires_at from public.glitch_user_connectors where user_id=auth.uid() $$;
revoke all on function public.list_glitch_connectors() from public,anon;grant execute on function public.list_glitch_connectors() to authenticated;
create or replace function public.disconnect_glitch_connector(p_provider text) returns boolean language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null then raise exception 'Authentication required';end if;delete from public.glitch_user_connectors where user_id=auth.uid() and provider=p_provider;return found;end $$;
revoke all on function public.disconnect_glitch_connector(text) from public,anon;grant execute on function public.disconnect_glitch_connector(text) to authenticated;
